<script setup>import {computed,reactive,ref} from 'vue';import {state,actions,displayTime} from '../../domain/prototypeStore.js';const q=ref(''),type=ref('全部'),status=ref('全部'),msg=ref(''),form=reactive({title:'',type:'消防告警',location:'东区展厅',description:''}),closure=reactive({evaluation:'',investigation:'',reportTitle:'',knowledgeNote:''});const rows=computed(()=>state.events.filter(e=>(!q.value||`${e.title}${e.location}`.includes(q.value))&&(type.value==='全部'||e.type===type.value)&&(status.value==='全部'||e.status===status.value)));const act=f=>{const r=f();msg.value=r.message||(r.ok?'操作成功':'操作未执行')};</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">事</div><div><h2>事件管理</h2><p>接报、核实、处置、续报和归档</p></div></div><article class="panel"><h3>新建事件</h3><div class="button-row"><input v-model="form.title" placeholder="事件名称"><select v-model="form.type"><option v-for="x in state.configs['事件类型']" :key="x">{{x}}</option></select><input v-model="form.location" placeholder="地点"><button class="primary-button active" @click="act(()=>actions.reportIncident(form,'Web'))">提交事件</button></div></article><div class="button-row"><input v-model="q" placeholder="关键词"><select v-model="type"><option>全部</option><option v-for="x in state.configs['事件类型']" :key="x">{{x}}</option></select><select v-model="status"><option>全部</option><option v-for="x in [...new Set(state.events.map(e=>e.status))]" :key="x">{{x}}</option></select></div><p v-if="msg" class="action-message">{{msg}}</p><article v-for="e in rows" :key="e.id" class="panel incident-card"><header><div><h3>{{e.title}}</h3><small>{{e.id}} · {{e.type}} · {{e.location}} · {{displayTime(e.createdAt)}}</small></div><strong>{{e.status}}</strong></header><p>{{e.description}}</p><div class="button-row"><button v-if="e.status==='待核实'" class="primary-button active" @click="act(()=>actions.verifyIncident(e.id,true))">核实通过</button><button v-if="e.status==='待核实'" class="secondary-button" @click="act(()=>actions.verifyIncident(e.id,false))">驳回</button><select v-if="e.status==='已核实'" @change="act(()=>actions.startIncident(e.id,$event.target.value))"><option value="">选择处置预案</option><option v-for="p in state.plans.filter(p=>p.status==='已发布')" :key="p.id" :value="p.id">{{p.name}}</option></select></div><section v-if="e.status==='处置中'" class="closure-panel"><h4>关闭材料</h4><div class="button-row"><input v-model="closure.evaluation" placeholder="评估结论"><input v-model="closure.investigation" placeholder="调查记录"><input v-model="closure.reportTitle" placeholder="事件报告名称"><button class="secondary-button" @click="act(()=>actions.submitClosure(e.id,closure))">保存材料</button><button class="primary-button active" @click="act(()=>actions.closeIncident(e.id))">关闭事件</button></div></section><details><summary>处置时间线</summary><ol class="timeline"><li v-for="x in e.timeline" :key="x.time+x.label"><time>{{displayTime(x.time)}}</time><div><strong>{{x.label}}</strong><p>{{x.detail}}</p></div></li></ol></details></article></section></template>
